#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long v1, v2;
} Line;

Line lines[100005];
long long v2s[100005];
long long bit[100005];
int M;

int cmpLine(const void *a, const void *b) {
    const Line *x = (const Line *)a;
    const Line *y = (const Line *)b;
    if (x->v1 < y->v1) return -1;
    if (x->v1 > y->v1) return 1;
    if (x->v2 < y->v2) return -1;
    if (x->v2 > y->v2) return 1;
    return 0;
}

int cmpLL(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

void bit_add(int idx, int val) {
    for (; idx <= M; idx += idx & -idx) {
        bit[idx] += val;
    }
}

long long bit_sum(int idx) {
    long long s = 0;
    for (; idx > 0; idx -= idx & -idx) {
        s += bit[idx];
    }
    return s;
}

int lower_bound_ll(long long *arr, int n, long long val) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) / 2;
        if (arr[m] < val) l = m + 1;
        else r = m;
    }
    return l;
}

int main() {
    int N;
    long long X1, X2;

    if (scanf("%d %lld %lld", &N, &X1, &X2) != 3) return 0;

    for (int i = 0; i < N; i++) {
        long long A, B;
        scanf("%lld %lld", &A, &B);
        lines[i].v1 = A * X1 + B;
        lines[i].v2 = A * X2 + B;
        v2s[i] = lines[i].v2;
    }

    qsort(lines, N, sizeof(Line), cmpLine);
    qsort(v2s, N, sizeof(long long), cmpLL);

    M = 0;
    for (int i = 0; i < N; i++) {
        if (i == 0 || v2s[i] != v2s[i - 1]) {
            v2s[M++] = v2s[i];
        }
    }

    long long ans = 0;
    int total_prev = 0;
    int i = 0;

    while (i < N) {
        int j = i + 1;
        while (j < N && lines[j].v1 == lines[i].v1) j++;

        int k = j - i;
        ans += (long long)k * (k - 1) / 2;

        for (int t = i; t < j; t++) {
            int pos = lower_bound_ll(v2s, M, lines[t].v2);
            int rank = pos + 1;
            long long less = bit_sum(rank - 1);
            ans += (long long)total_prev - less;
        }

        for (int t = i; t < j; t++) {
            int pos = lower_bound_ll(v2s, M, lines[t].v2);
            bit_add(pos + 1, 1);
            total_prev++;
        }

        i = j;
    }

    printf("%lld\n", ans);
    return 0;
}
